import{_ as o,o as t,c as e,a6 as n}from"./chunks/framework.QQy01QNh.js";const r="/xi-kari-skill/handbook/images/toyota-andon.svg",m=JSON.parse('{"title":"丰田Andon：异常被看见之后，流程怎样继续","description":"","frontmatter":{"slug":"toyota-andon","title":"丰田Andon：异常被看见之后，流程怎样继续","kind":"真实案例","source_type":"企业官方流程与历史资料","concepts":["effective-feedback","carrier-and-responsibility","carried-learning"]},"headers":[],"relativePath":"cases/toyota-andon.md","filePath":"cases/toyota-andon.md"}'),i={name:"cases/toyota-andon.md"};function s(l,a,d,c,h,p){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="丰田andon-异常被看见之后-流程怎样继续" tabindex="-1">丰田Andon：异常被看见之后，流程怎样继续 <a class="header-anchor" href="#丰田andon-异常被看见之后-流程怎样继续" aria-label="Permalink to &quot;丰田Andon：异常被看见之后，流程怎样继续&quot;">​</a></h1><p>一盏显示异常的灯，什么时候只是通知，什么时候成为处理过程的一部分？丰田的官方工厂介绍提供了一个具体入口：工人发现问题后按下呼叫按钮，Andon显示板通知负责人；问题解决前，工作不恢复。这是企业对自身流程的公开说明。<a href="https://global.toyota/en/company/plant-tours/production-system/" target="_blank" rel="noreferrer">丰田虚拟工厂：Jidoka与Andon</a></p><h2 id="显示板接在什么关系里" tabindex="-1">显示板接在什么关系里 <a class="header-anchor" href="#显示板接在什么关系里" aria-label="Permalink to &quot;显示板接在什么关系里&quot;">​</a></h2><p>丰田另一份官方说明将两种情形分开：设备因异常停止后，Andon亮起通知工作人员；没有设备的产线也可以通过拉停止绳点亮Andon、呼叫负责人。这几种流程的连接不同，灯亮并不统一等于机器立即停止。显示、停止、呼叫和处理之间的安排，要按具体流程辨认。<a href="https://global.toyota/en/company/vision-and-philosophy/production-system/" target="_blank" rel="noreferrer">丰田生产方式说明</a></p><p>其公司历史资料还记录，1955年，本社工厂的Crown装配线采用了与停止按钮联动的Andon，以便识别导致停线的工序。这使读者看到，显示位置和处理对象之间可以有明确的制度与设备连接。<a href="https://www.toyota-global.com/company/history_of_toyota/75years/common/pdf/production_system.pdf" target="_blank" rel="noreferrer">丰田75年史：生产方式沿革</a></p><figure class="concept-figure"><img src="'+r+'" alt="toyota-andon案例的关系图"><figcaption>根据本页官方资料绘制，保留图示的适用范围。</figcaption></figure><h2 id="从这里读懂有效反馈" tabindex="-1">从这里读懂有效反馈 <a class="header-anchor" href="#从这里读懂有效反馈" aria-label="Permalink to &quot;从这里读懂有效反馈&quot;">​</a></h2><p>《Xikari-条件结构与转化论》的D2定义要求追踪先前状态或输出、返回通道、接收位置以及被改变的后续字段。信号到达与后续状态改变是两项判断。阅读Andon流程时，可以沿异常怎样被发现、怎样到达负责人、怎样影响继续工作的条件看下去。灯光本身可见，并不代替后面的处理。<a href="/xi-kari-skill/handbook/theory/part-03.html#section-3-3">阅读原文：§3.3有效反馈</a></p><p>这个阅读连接也保留一个界限：官方流程介绍能够说明企业公开描述了怎样的安排，不能单凭它估计每个工厂、每次呼叫的实际执行率，或某项措施独立带来了多少质量改善。若要作那些判断，需要对应地点、时期、任务和比较材料。</p><h2 id="一次处理-还不是长期学习的全部" tabindex="-1">一次处理，还不是长期学习的全部 <a class="header-anchor" href="#一次处理-还不是长期学习的全部" aria-label="Permalink to &quot;一次处理，还不是长期学习的全部&quot;">​</a></h2><p>原文进一步区分有效反馈与载体学习：异常得到一次处理之后，还须看更新是否保留、后续轮次是否实际调用，以及预定任务结果怎样变化。因此，“发现—呼叫—处理—恢复”这段流程成立，并不能自动证明组织已经学会。规则、设备或操作知识怎样留下并被再用，属于需要继续取得依据的问题。<a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">阅读原文：§6.3反馈介导学习</a></p><p>读这个案例，先把通知、处理、后续改变和长期学习分别看清，才能理解每一段安排究竟完成了什么。</p><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="./../concepts/responsibility.html">实际承接与责任依据</a></li><li><a href="./../concepts/feedback.html">从收到信息到有效反馈</a></li><li><a href="./../concepts/history.html">更新怎样保留并在后来被调用</a></li></ul>',14)])])}const _=o(i,[["render",s]]);export{m as __pageData,_ as default};
